def txt(sl,x,y,w,h,value,size=20,bold=False,fg=None):
 shape=sl.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h));tf=shape.text_frame;tf.word_wrap=True
 for i,line in enumerate(value.split('\n')):
  par=tf.paragraphs[0] if i==0 else tf.add_paragraph();par.text=line;par.font.name='Arial';par.font.size=Pt(size);par.font.bold=bold;par.font.color.rgb=color(fg or pal['grey-900']);par.space_after=Pt(12)
htmlSlides=[]
for i,(title,take,bullets,file) in enumerate(slides,1):
 sl=prs.slides.add_slide(prs.slide_layouts[6]);sl.background.fill.solid();sl.background.fill.fore_color.rgb=color(pal['grey-50']);txt(sl,.5,.25,12,.3,f'VINCLUB / PHƯƠNG ÁN CUỐI / {i:02}',11,True);txt(sl,.5,.9,8.3,1.1,title,32,True);txt(sl,.5,2.1,8.2,1.1,take,21,False,pal['grey-600']);txt(sl,.5,3.5,8,2.9,'\n'.join('• '+x for x in bullets),19)
 fp=R/'evidence'/f'{file}.png' if file else None;pic=''
 if fp and fp.exists():
  from PIL import Image
  w,h=Image.open(fp).size
  if h/w>1.5:sl.shapes.add_picture(str(fp),Inches(9.6),Inches(1),height=Inches(5.9))
  else:sl.shapes.add_picture(str(fp),Inches(8.8),Inches(2.3),width=Inches(4.0))
  pic=f'<img src="evidence/{file}.png" alt="{e(title)}">'
 txt(sl,.5,7,12,.3,'Đo source / compose code · Không có human UT · Bản đề xuất không phải giao dịch thật',10,False,pal['grey-600'])
 htmlSlides.append(f'<section class="slide"><div><small>VINCLUB / FINAL / {i:02}</small><h1>{e(title)}</h1><h2>{e(take)}</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in bullets)+f'</ul></div>{pic}<footer>Source làm chuẩn · API / giao dịch thật chưa nghiệm thu</footer></section>')
